def evaluate(current_reputation, observation, my_history, round_num):
    # Update reputation based on observed actions in the current round
    if observation['action'] == 'cooperate':
        # Positive behavior observed, increase reputation with diminishing returns
        new_reputation = current_reputation + 0.15 * (1 - abs(current_reputation))
    else:  # defect
        # Negative behavior observed, decrease reputation with diminishing returns
        new_reputation = current_reputation - 0.15 * (1 - abs(current_reputation))

    # Clamp to [-1.0, 1.0]
    return max(-1.0, min(1.0, new_reputation))


